19: const rand = (min: number, max: number): number => min + Math.random() * (max - min);
20: const clamp = (value: number, min: number, max: number): number =>
21:   value < min ? min : value > max ? max : value;
22: const rrect = (x: number, y: number, w: number, h: number, r: number): void => {
23:   const radius = Math.min(r, w / 2, h / 2);
24:   ctx.beginPath();
25:   ctx.moveTo(x + radius, y);
26:   ctx.arcTo(x + w, y, x + w, y + h, radius);
27:   ctx.arcTo(x + w, y + h, x, y + h, radius);
28:   ctx.arcTo(x, y + h, x, y, radius);
29:   ctx.arcTo(x, y, x + w, y, radius);
30:   ctx.closePath();
31: };
