37: class Sound {
38:   private audioCtx: AudioContext | null = null;
39:   muted = false;
40: 
41:   unlock(): void {
42:     if (!this.audioCtx) {
43:       const Ctor =
44:         window.AudioContext ??
45:         (window as unknown as { webkitAudioContext?: typeof AudioContext })
46:           .webkitAudioContext;
47:       if (!Ctor) return;
48:       this.audioCtx = new Ctor();
49:     }
50:     if (this.audioCtx.state === "suspended") void this.audioCtx.resume();
51:   }
52: 
53:   blip(
54:     freq: number,
55:     dur: number,
56:     type: OscillatorType = "square",
57:     vol = 0.08,
58:     slideTo = 0,
59:   ): void {
60:     if (this.muted || !this.audioCtx || this.audioCtx.state !== "running") return;
61:     const t = this.audioCtx.currentTime;
62:     const osc = this.audioCtx.createOscillator();
63:     const gain = this.audioCtx.createGain();
64:     osc.type = type;
65:     osc.frequency.setValueAtTime(freq, t);
66:     if (slideTo > 0) osc.frequency.exponentialRampToValueAtTime(slideTo, t + dur);
67:     gain.gain.setValueAtTime(vol, t);
68:     gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
69:     osc.connect(gain).connect(this.audioCtx.destination);
70:     osc.start(t);
71:     osc.stop(t + dur + 0.02);
72:   }
