159:   "3": { fill: "#ff6b9d", glow: "rgba(255,107,157,0.8)", hp: 3, score: 200 },
160:   X: { fill: "#ff5f4d", glow: "rgba(255,95,77,0.95)", hp: 1, score: 150 },
