163: const COLS = 12;
164: const BRICK_TOP = HUD_H + 34;
165: const BRICK_LEFT = WALL + 8;
166: const PLAY_W = W - BRICK_LEFT * 2;
167: const BRICK_W = PLAY_W / COLS;
168: const BRICK_H = 26;
169: const BRICK_GAP = 2;
