171: // ---------------------------------------------------------------------------
172: // Power-ups
173: // ---------------------------------------------------------------------------
174: 
175: type PowerKind = "WIDE" | "MULTI" | "SLOW" | "LASER" | "LIFE";
176: 
177: const POWER_STYLE: Record<
178:   PowerKind,
179:   { label: string; color: string; weight: number }
180: > = {
181:   WIDE: { label: "W", color: "#7dfcff", weight: 28 },
182:   MULTI: { label: "M", color: "#b48cff", weight: 24 },
183:   SLOW: { label: "S", color: "#7dff9e", weight: 20 },
184:   LASER: { label: "L", color: "#ffd166", weight: 18 },
185:   LIFE: { label: "+", color: "#ff6b9d", weight: 10 },
186: };
187: 
188: const POWER_LIST = Object.keys(POWER_STYLE) as PowerKind[];
189: 
190: function rollPower(): PowerKind | null {
191:   if (Math.random() > 0.14) return null;
192:   const total = POWER_LIST.reduce((sum, k) => sum + POWER_STYLE[k].weight, 0);
193:   let ticket = Math.random() * total;
194:   for (const kind of POWER_LIST) {
195:     ticket -= POWER_STYLE[kind].weight;
196:     if (ticket <= 0) return kind;
197:   }
198:   return "WIDE";
199: }
