254: type GameState = "menu" | "playing" | "paused" | "clear" | "over";
255: 
256: // ---------------------------------------------------------------------------
257: // Game
258: // ---------------------------------------------------------------------------
259: 
260: const STORAGE_KEY = "nova-breaker-highscore";
261: 
262: class Game {
263:   state: GameState = "menu";
264:   score = 0;
265:   best = 0;
266:   level = 1;
267:   lives = 3;
268:   combo = 0;
269: 
270:   paddleW = 132;
271:   paddleBaseW = 132;
272:   paddleX = W / 2;
273:   paddleTargetX = W / 2;
274: 
275:   balls: Ball[] = [];
276:   bricks: Brick[] = [];
277:   drops: Drop[] = [];
278:   lasers: Laser[] = [];
279:   particles: Particle[] = [];
280:   floats: FloatText[] = [];
281: 
282:   wideTimer = 0;
283:   slowTimer = 0;
284:   laserTimer = 0;
285:   laserCooldown = 0;
286:   laserToShoot = false;
287: 
288:   shake = 0;
289:   keyLeft = false;
290:   keyRight = false;
291: 
292:   constructor() {
293:     try {
294:       this.best = Number(localStorage.getItem(STORAGE_KEY) ?? "0") || 0;
295:     } catch {
296:       this.best = 0;
297:     }
298:   }
299: 
300:   // ---- lifecycle --------------------------------------------------------
301: 
302:   startRun(): void {
303:     this.score = 0;
304:     this.level = 1;
305:     this.lives = 3;
306:     this.combo = 0;
307:     this.drops = [];
308:     this.lasers = [];
309:     this.wideTimer = this.slowTimer = this.laserTimer = 0;
310:     this.paddleW = this.paddleBaseW;
311:     this.loadLevel(this.level);
312:     this.state = "playing";
313:   }
314: 
315:   nextLevel(): void {
316:     this.level += 1;
317:     this.combo = 0;
318:     this.drops = [];
319:     this.lasers = [];
320:     this.wideTimer = this.slowTimer = this.laserTimer = 0;
321:     this.paddleW = this.paddleBaseW;
322:     this.loadLevel(this.level);
323:     this.state = "playing";
324:   }
325: 
326:   loadLevel(level: number): void {
327:     const pattern = LEVELS[(level - 1) % LEVELS.length];
328:     const speedBoost = Math.floor((level - 1) / LEVELS.length); // extra armor each full loop
329:     this.bricks = [];
330:     pattern.forEach((line, row) => {
331:       for (let col = 0; col < COLS; col++) {
332:         const type = line[col] ?? ".";
333:         if (type === ".") continue;
334:         let hp = BRICK_STYLE[type]?.hp ?? 1;
335:         if (type !== "X" && speedBoost > 0) hp += speedBoost;
336:         this.bricks.push({
337:           col,
338:           row,
339:           type,
340:           hp,
341:           maxHp: hp,
342:           alive: true,
343:           hitFlash: 0,
344:         });
345:       }
346:     });
347:     this.resetBallAndPaddle();
348:   }
349: 
350:   resetBallAndPaddle(): void {
351:     this.paddleX = W / 2;
352:     this.paddleTargetX = W / 2;
353:     this.balls = [this.newBall()];
354:   }
355: 
356:   newBall(): Ball {
357:     return {
358:       x: this.paddleX,
359:       y: H - 70,
360:       vx: 0,
361:       vy: 0,
362:       stuck: true,
363:     };
364:   }
365: 
366:   ballSpeed(): number {
367:     const base = 330 + (this.level - 1) * 16;
368:     return Math.min(base, 540);
369:   }
370: 
371:   // ---- input ------------------------------------------------------------
372: 
373:   pressAction(): void {
374:     if (this.state === "menu") {
375:       sound.unlock();
376:       this.startRun();
377:       return;
378:     }
379:     if (this.state === "over") {
380:       this.startRun();
381:       return;
382:     }
383:     if (this.state === "clear") {
384:       this.nextLevel();
385:       return;
386:     }
387:     if (this.state !== "playing") return;
388:     this.launchOrShoot();
389:   }
390: 
391:   launchOrShoot(): void {
392:     let launched = false;
393:     for (const ball of this.balls) {
394:       if (ball.stuck) {
395:         const speed = this.ballSpeed();
396:         const angle = rand(-0.55, 0.55) - Math.PI / 2;
397:         ball.vx = Math.cos(angle) * speed;
398:         ball.vy = Math.sin(angle) * speed;
399:         ball.stuck = false;
400:         launched = true;
401:       }
402:     }
403:     if (launched) sound.paddleHit();
404:     else if (this.laserTimer > 0 && this.laserCooldown <= 0) this.shoot();
405:   }
406: 
407:   shoot(): void {
408:     this.lasers.push({ x: this.paddleX - this.paddleW / 2 + 12, y: H - 64 });
409:     this.lasers.push({ x: this.paddleX + this.paddleW / 2 - 12, y: H - 64 });
410:     this.laserCooldown = 0.24;
411:     sound.laser();
412:   }
413: 
414:   togglePause(): void {
415:     if (this.state === "playing") this.state = "paused";
416:     else if (this.state === "paused") this.state = "playing";
417:   }
418: 
419:   // ---- simulation -------------------------------------------------------
420: 
421:   update(dt: number): void {
422:     if (this.state !== "playing") {
423:       this.stepParticles(dt);
424:       return;
425:     }
426: 
427:     // timers
428:     this.wideTimer = Math.max(0, this.wideTimer - dt);
429:     this.slowTimer = Math.max(0, this.slowTimer - dt);
430:     this.laserTimer = Math.max(0, this.laserTimer - dt);
431:     this.laserCooldown = Math.max(0, this.laserCooldown - dt);
432:     if (this.wideTimer === 0) this.paddleW = this.paddleBaseW;
433:     this.shake = Math.max(0, this.shake - dt * 40);
434: 
435:     // paddle: keyboard nudges the target, pointer sets it directly
436:     const keyStep = 620 * dt;
437:     if (this.keyLeft) this.paddleTargetX -= keyStep;
438:     if (this.keyRight) this.paddleTargetX += keyStep;
439:     const half = this.paddleW / 2;
440:     this.paddleTargetX = clamp(this.paddleTargetX, WALL + half, W - WALL - half);
441:     this.paddleX = this.paddleTargetX;
442: 
443:     const slowFactor = this.slowTimer > 0 ? 0.62 : 1;
444: 
445:     // balls
446:     let lostAny = false;
447:     for (const ball of this.balls) {
448:       if (ball.stuck) {
449:         ball.x = clamp(this.paddleX, WALL + 8, W - WALL - 8);
450:         ball.y = H - 70;
451:         continue;
452:       }
453:       // keep speed near target (slow-field shrinks it, restores after)
454:       const mag = Math.hypot(ball.vx, ball.vy) || 1;
455:       const target = this.ballSpeed() * slowFactor;
456:       const scale = target / mag;
457:       ball.vx *= scale;
458:       ball.vy *= scale;
459: 
460:       const steps = Math.max(1, Math.ceil((Math.hypot(ball.vx, ball.vy) * dt) / 8));
461:       const sub = dt / steps;
462:       for (let i = 0; i < steps; i++) {
463:         ball.x += ball.vx * sub;
464:         ball.y += ball.vy * sub;
465:         this.collideWalls(ball);
466:         this.collidePaddle(ball);
467:         this.collideBricks(ball);
468:         if (ball.y - 8 > H) {
469:           lostAny = true;
470:           break;
471:         }
472:         if (this.state !== "playing") return;
473:       }
474:       if (lostAny) break;
475:     }
476:     this.balls = this.balls.filter((b) => b.y - 8 <= H);
477: 
478:     if (this.balls.length === 0) {
479:       this.loseLife();
480:       if (this.state !== "playing") return;
481:     }
482:     if (this.laserTimer === 0) this.lasers.length = 0;
483: 
484:     // lasers
485:     for (const laser of this.lasers) {
486:       laser.y -= 700 * dt;
487:     }
488:     this.lasers = this.lasers.filter((l) => l.y > BRICK_TOP - 30);
489:     for (const laser of [...this.lasers]) {
490:       for (const brick of this.bricks) {
491:         if (!brick.alive) continue;
492:         const b = this.brickRect(brick);
493:         if (laser.x > b.x && laser.x < b.x + b.w && laser.y < b.y + b.h && laser.y > b.y) {
494:           this.hitBrick(brick, laser.x, laser.y);
495:           this.lasers = this.lasers.filter((l) => l !== laser);
496:           break;
497:         }
498:       }
499:     }
500: 
501:     // drops
502:     for (const drop of this.drops) {
503:       drop.y += drop.vy * dt;
504:       drop.vy = Math.min(drop.vy + 200 * dt, 420);
505:       if (
506:         drop.y > H - 60 &&
507:         drop.y < H - 34 &&
508:         Math.abs(drop.x - this.paddleX) < this.paddleW / 2 + 14
509:       ) {
510:         this.applyPower(drop.kind, drop.x);
511:         drop.y = H * 2; // consume
512:       }
513:     }
514:     this.drops = this.drops.filter((d) => d.y < H + 20);
515: 
516:     // brick flash decay + level clear check
517:     for (const brick of this.bricks) {
518:       if (brick.hitFlash > 0) brick.hitFlash = Math.max(0, brick.hitFlash - dt * 5);
519:     }
520:     this.stepParticles(dt);
521: 
522:     if (this.bricks.every((b) => !b.alive)) {
523:       this.state = "clear";
524:       this.score += 500 + this.level * 100;
525:       if (this.score > this.best) this.saveBest();
526:       sound.clear();
527:     }
528:   }
529: 
530:   stepParticles(dt: number): void {
531:     for (const p of this.particles) {
532:       p.x += p.vx * dt;
533:       p.y += p.vy * dt;
534:       p.vy += 420 * dt;
535:       p.life -= dt;
536:     }
537:     this.particles = this.particles.filter((p) => p.life > 0);
538:     for (const f of this.floats) {
539:       f.y -= 40 * dt;
540:       f.life -= dt;
541:     }
542:     this.floats = this.floats.filter((f) => f.life > 0);
543:   }
544: 
545:   collideWalls(ball: Ball): void {
546:     const r = 8;
547:     if (ball.x - r < WALL) {
548:       ball.x = WALL + r;
549:       ball.vx = Math.abs(ball.vx);
550:       sound.blip(180, 0.05, "sine", 0.05);
551:     } else if (ball.x + r > W - WALL) {
552:       ball.x = W - WALL - r;
553:       ball.vx = -Math.abs(ball.vx);
554:       sound.blip(180, 0.05, "sine", 0.05);
555:     }
556:     if (ball.y - r < HUD_H) {
557:       ball.y = HUD_H + r;
558:       ball.vy = Math.abs(ball.vy);
559:       sound.blip(180, 0.05, "sine", 0.05);
560:     }
561:   }
562: 
563:   collidePaddle(ball: Ball): void {
564:     const r = 8;
565:     const top = H - 46;
566:     if (ball.vy <= 0) return;
567:     if (ball.y + r < top || ball.y - r > top + 14) return;
568:     if (ball.x < this.paddleX - this.paddleW / 2 - r) return;
569:     if (ball.x > this.paddleX + this.paddleW / 2 + r) return;
570:     ball.y = top - r;
571:     this.combo = 0;
572:     const rel = clamp((ball.x - this.paddleX) / (this.paddleW / 2), -1, 1);
573:     const speed = Math.hypot(ball.vx, ball.vy) || this.ballSpeed();
574:     const angle = rel * 1.05 - Math.PI / 2; // -105° .. -75° widened by hit offset
575:     ball.vx = Math.cos(angle) * speed;
576:     ball.vy = Math.sin(angle) * speed;
577:     sound.paddleHit();
578:     this.spawnParticles(ball.x, top, 6, "#7dfcff");
579:   }
580: 
581:   brickRect(brick: Brick): { x: number; y: number; w: number; h: number } {
582:     return {
583:       x: BRICK_LEFT + brick.col * BRICK_W + BRICK_GAP,
584:       y: BRICK_TOP + brick.row * (BRICK_H + BRICK_GAP),
585:       w: BRICK_W - BRICK_GAP * 2,
586:       h: BRICK_H,
587:     };
588:   }
589: 
590:   collideBricks(ball: Ball): void {
591:     const r = 8;
592:     for (const brick of this.bricks) {
593:       if (!brick.alive) continue;
594:       const b = this.brickRect(brick);
595:       if (ball.x + r < b.x || ball.x - r > b.x + b.w) continue;
596:       if (ball.y + r < b.y || ball.y - r > b.y + b.h) continue;
597: 
598:       // resolve bounce axis: choose smaller penetration side
599:       const overlapLeft = ball.x + r - b.x;
600:       const overlapRight = b.x + b.w - (ball.x - r);
601:       const overlapTop = ball.y + r - b.y;
602:       const overlapBottom = b.y + b.h - (ball.y - r);
603:       const minHoriz = Math.min(overlapLeft, overlapRight);
604:       const minVert = Math.min(overlapTop, overlapBottom);
605:       if (minHoriz < minVert) {
606:         ball.vx = -ball.vx;
607:         ball.x += overlapLeft < overlapRight ? -minHoriz : minHoriz;
608:       } else {
609:         ball.vy = -ball.vy;
610:         ball.y += overlapTop < overlapBottom ? -minVert : minVert;
611:       }
612:       this.hitBrick(brick, ball.x, ball.y);
613:       break;
614:     }
615:   }
616: 
617:   hitBrick(brick: Brick, hx: number, hy: number): void {
618:     brick.hp -= 1;
619:     brick.hitFlash = 1;
620:     if (brick.hp > 0) {
621:       sound.brickHit();
622:       this.spawnParticles(hx, hy, 4, BRICK_STYLE[brick.type]?.fill ?? "#ffffff");
623:       return;
624:     }
625:     brick.alive = false;
626:     this.combo += 1;
627:     const style = BRICK_STYLE[brick.type] ?? { fill: "#ffffff", score: 50, glow: "" };
628:     const mult = Math.min(this.combo, 8);
629:     const gained = style.score * mult;
630:     this.score += gained;
631:     if (this.score > this.best) this.saveBest();
632:     this.floats.push({
633:       x: hx,
634:       y: hy,
635:       text: mult > 1 ? `+${gained} x${mult}` : `+${gained}`,
636:       life: 0.9,
637:       color: style.fill,
638:     });
639:     const rect = this.brickRect(brick);
640:     this.spawnParticles(
641:       rect.x + rect.w / 2,
642:       rect.y + rect.h / 2,
643:       14,
644:       style.fill,
645:     );
646:     sound.brickBreak(this.combo);
647: 
648:     if (brick.type === "X") {
649:       sound.explosion();
650:       this.shake = 14;
651:       this.spawnParticles(hx, hy, 26, "#ff8c5f");
652:       for (const other of this.bricks) {
653:         if (!other.alive || other === brick) continue;
654:         const o = this.brickRect(other);
655:         const dx = o.x + o.w / 2 - (rect.x + rect.w / 2);
656:         const dy = o.y + o.h / 2 - (rect.y + rect.h / 2);
657:         if (Math.abs(dx) <= BRICK_W * 1.5 && Math.abs(dy) <= BRICK_H * 2.5) {
658:           // chain via damage so armored neighbors can survive an edge hit
659:           other.hp -= 1;
660:           other.hitFlash = 1;
661:           if (other.hp <= 0) this.hitBrick(other, o.x + o.w / 2, o.y + o.h / 2);
662:         }
663:       }
664:     }
665: 
666:     const kind = rollPower();
667:     if (kind) {
668:       this.drops.push({
669:         x: rect.x + rect.w / 2,
670:         y: rect.y + rect.h / 2,
671:         vy: 140,
672:         kind,
673:       });
674:     }
675:   }
676: 
677:   applyPower(kind: PowerKind, x: number): void {
678:     sound.powerup();
679:     switch (kind) {
680:       case "WIDE":
681:         this.wideTimer = 12;
682:         this.paddleW = this.paddleBaseW * 1.5;
683:         break;
684:       case "MULTI": {
685:         const live = this.balls.filter((b) => !b.stuck).slice(0, 1);
686:         const extra: Ball[] = [];
687:         for (const src of live) {
688:           for (const dir of [-1, 1]) {
689:             const speed = Math.hypot(src.vx, src.vy) || this.ballSpeed();
690:             const angle = Math.atan2(src.vy, src.vx) + dir * 0.5;
691:             extra.push({
692:               x: src.x,
693:               y: src.y,
694:               vx: Math.cos(angle) * speed,
695:               vy: Math.sin(angle) * speed,
696:               stuck: false,
697:             });
698:           }
699:         }
700:         if (extra.length === 0) {
701:           // all stuck: spawn two loose balls slightly above the paddle
702:           for (const dir of [-1, 1]) {
703:             const speed = this.ballSpeed();
704:             const angle = -Math.PI / 2 + dir * 0.5;
705:             extra.push({
706:               x: this.paddleX + dir * 20,
707:               y: H - 90,
708:               vx: Math.cos(angle) * speed,
709:               vy: Math.sin(angle) * speed,
710:               stuck: false,
711:             });
712:           }
713:         }
714:         this.balls.push(...extra);
715:         break;
716:       }
717:       case "SLOW":
718:         this.slowTimer = 8;
719:         break;
720:       case "LASER":
721:         this.laserTimer = 10;
722:         break;
723:       case "LIFE":
724:         this.lives = Math.min(5, this.lives + 1);
725:         break;
726:     }
727:     this.floats.push({
728:       x,
729:       y: H - 80,
730:       text: POWER_STYLE[kind].label === "+" ? "+1 LIFE" : POWER_STYLE[kind].label,
731:       life: 1,
732:       color: POWER_STYLE[kind].color,
733:     });
734:   }
735: 
736:   loseLife(): void {
737:     this.lives -= 1;
738:     this.combo = 0;
739:     sound.death();
740:     this.shake = 18;
741:     if (this.lives <= 0) {
742:       this.state = "over";
743:       if (this.score > this.best) this.saveBest();
744:       sound.gameOver();
745:       return;
746:     }
747:     this.drops = [];
748:     this.lasers = [];
749:     this.wideTimer = this.slowTimer = this.laserTimer = 0;
750:     this.paddleW = this.paddleBaseW;
751:     this.resetBallAndPaddle();
752:   }
753: 
754:   saveBest(): void {
755:     this.best = this.score;
756:     try {
757:       localStorage.setItem(STORAGE_KEY, String(this.best));
758:     } catch {
759:       // storage unavailable — best score stays for the session only
760:     }
761:   }
762: 
763:   spawnParticles(x: number, y: number, count: number, color: string): void {
764:     for (let i = 0; i < count; i++) {
765:       const angle = rand(0, Math.PI * 2);
766:       const speed = rand(40, 260);
767:       this.particles.push({
768:         x,
769:         y,
770:         vx: Math.cos(angle) * speed,
771:         vy: Math.sin(angle) * speed - 60,
772:         life: rand(0.25, 0.7),
773:         maxLife: 0.7,
774:         size: rand(1.5, 3.5),
775:         color,
776:       });
777:     }
778:     if (this.particles.length > 400) this.particles.splice(0, this.particles.length - 400);
779:   }
780: }
