870: function drawBackground(): void {
871:   const grad = ctx.createLinearGradient(0, 0, 0, H);
872:   grad.addColorStop(0, "#0b1030");
873:   grad.addColorStop(0.55, "#090d22");
874:   grad.addColorStop(1, "#05070f");
