881:   ctx.beginPath();
882:   for (let x = WALL; x <= W - WALL; x += 40) {
883:     ctx.moveTo(x, HUD_H);
884:     ctx.lineTo(x, H);
885:   }
886:   for (let y = HUD_H; y <= H; y += 40) {
887:     ctx.moveTo(WALL, y);
888:     ctx.lineTo(W - WALL, y);
889:   }
890:   ctx.stroke();
891: 
892:   // neon frame
893:   ctx.shadowColor = "rgba(125,252,255,0.7)";
