895:   ctx.strokeStyle = "rgba(125,252,255,0.45)";
896:   ctx.lineWidth = 2;
897:   ctx.strokeRect(WALL / 2, WALL / 2, W - WALL, H - WALL / 2);
898:   ctx.shadowBlur = 0;
