950: function drawBricks(): void {
951:   for (const brick of game.bricks) {
952:     if (!brick.alive) continue;
953:     const b = game.brickRect(brick);
954:     const style = BRICK_STYLE[brick.type] ?? BRICK_STYLE["1"];
955:     const damaged = brick.hp < brick.maxHp;
956:     ctx.shadowColor = style.glow;
957:     ctx.shadowBlur = brick.type === "X" ? 14 : 8;
958:     ctx.fillStyle = damaged ? shade(style.fill) : style.fill;
959:     rrect(b.x, b.y, b.w, b.h, 5);
960:     ctx.fill();
961:     ctx.shadowBlur = 0;
962:     if (brick.hitFlash > 0) {
963:       ctx.fillStyle = `rgba(255,255,255,${brick.hitFlash * 0.55})`;
964:       rrect(b.x, b.y, b.w, b.h, 5);
965:       ctx.fill();
966:     }
967:     // armored bricks show remaining hit pips
968:     if (brick.maxHp > 1) {
969:       ctx.fillStyle = "rgba(10,14,30,0.65)";
970:       for (let i = 0; i < brick.hp; i++) {
971:         ctx.beginPath();
972:         ctx.arc(b.x + 10 + i * 10, b.y + b.h / 2, 3, 0, Math.PI * 2);
973:         ctx.fill();
974:       }
975:     }
976:   }
977: }
