979: const shadeCache = new Map<string, string>();
980: 
981: function shade(color: string): string {
982:   const cached = shadeCache.get(color);
983:   if (cached) return cached;
984:   const m = color.match(/^#([0-9a-f]{6})$/i);
985:   if (!m) return color;
986:   const n = parseInt(m[1], 16);
987:   const dims = [Math.round(((n >> 16) & 255) * 0.55), Math.round(((n >> 8) & 255) * 0.55), Math.round((n & 255) * 0.55)];
988:   const out = `#${dims.map((c) => c.toString(16).padStart(2, "0")).join("")}`;
989:   shadeCache.set(color, out);
990:   return out;
991: }
