1052: function drawParticles(): void {
1053:   for (const p of game.particles) {
1054:     ctx.globalAlpha = clamp(p.life / p.maxLife, 0, 1);
1055:     ctx.fillStyle = p.color;
1056:     ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
1057:   }
