1059:   for (const f of game.floats) {
1060:     ctx.globalAlpha = clamp(f.life, 0, 1);
1061:     ctx.fillStyle = f.color;
1062:     ctx.font = "700 15px 'Segoe UI', system-ui, sans-serif";
1063:     ctx.textAlign = "center";
1064:     ctx.textBaseline = "middle";
1065:     ctx.fillText(f.text, f.x, f.y);
