// NOVA BREAKER Game Testing Suite
// This file contains comprehensive tests to verify the game is complete and functional

const fs = require('fs');
const path = require('path');

// Test 1: Verify game file exists and has sufficient code
function testGameFileExists() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    if (!fs.existsSync(gameFile)) {
        throw new Error('Game file not found: src/game/main.ts');
    }
    console.log('✅ Game file exists');
    return true;
}

// Test 2: Verify game file has substantial code (should be ~1159 lines)
function testGameCodeLength() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    const content = fs.readFileSync(gameFile, 'utf8');
    const lines = content.split('\n').filter(line => line.trim() && !line.trim().startsWith('//'));

    if (lines.length < 1000) {
        throw new Error(`Game file appears incomplete: only ${lines.length} lines of code`);
    }
    console.log(`✅ Game has substantial code: ${lines.length} lines`);
    return true;
}

// Test 3: Verify game file contains key components
function testGameComponents() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    const content = fs.readFileSync(gameFile, 'utf8');

    const requiredComponents = [
        'interface Ball',
        'interface Brick', 
        'interface Game',
        'class Sound',
        'const LEVELS:',
        'const BRICK_STYLE:',
        'function drawBackground',
        'function render()',
        'function frame()',
        'requestAnimationFrame(frame)'
    ];

    const missing = requiredComponents.filter(comp => !content.includes(comp));
    if (missing.length > 0) {
        throw new Error(`Game missing required components: ${missing.join(', ')}`);
    }
    console.log('✅ Game contains all required components');
    return true;
}

// Test 4: Verify game.html exists and references the game
function testGameHtmlExists() {
    const gameHtml = path.join(__dirname, 'game.html');
    if (!fs.existsSync(gameHtml)) {
        throw new Error('game.html not found');
    }

    const content = fs.readFileSync(gameHtml, 'utf8');
    if (!content.includes('src/game/main.ts')) {
        throw new Error('game.html does not reference game source');
    }
    console.log('✅ game.html exists and references game source');
    return true;
}

// Test 5: Verify power-ups system is present
function testPowerUpsSystem() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    const content = fs.readFileSync(gameFile, 'utf8');

    const powerUpComponents = [
        'type PowerKind',
        'POWER_STYLE:',
        'POWER_LIST',
        'rollPower()',
        'applyPower('
    ];

    const missing = powerUpComponents.filter(comp => !content.includes(comp));
    if (missing.length > 0) {
        throw new Error(`Power-ups system incomplete: ${missing.join(', ')}`);
    }
    console.log('✅ Power-ups system is complete');
    return true;
}

// Test 6: Verify levels system is present
function testLevelsSystem() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    const content = fs.readFileSync(gameFile, 'utf8');

    const levelComponents = [
        'const LEVELS:',
        'loadLevel(',
        'nextLevel()',
        'startRun()'
    ];

    const missing = levelComponents.filter(comp => !content.includes(comp));
    if (missing.length > 0) {
        throw new Error(`Levels system incomplete: ${missing.join(', ')}`);
    }
    console.log('✅ Levels system is complete');
    return true;
}

// Test 7: Verify audio system is present
function testAudioSystem() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    const content = fs.readFileSync(gameFile, 'utf8');

    const audioComponents = [
        'class Sound',
        'blip(',
        'paddleHit(',
        'brickHit(',
        'brickBreak(',
        'explosion(',
        'powerup(',
        'laser(',
        'death(',
        'clear(',
        'gameOver('
    ];

    const missing = audioComponents.filter(comp => !content.includes(comp));
    if (missing.length > 0) {
        throw new Error(`Audio system incomplete: ${missing.join(', ')}`);
    }
    console.log('✅ Audio system is complete');
    return true;
}

// Test 8: Verify high score persistence
function testHighScorePersistence() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    const content = fs.readFileSync(gameFile, 'utf8');

    if (!content.includes('localStorage') || !content.includes('STORAGE_KEY')) {
        throw new Error('High score persistence not found');
    }
    console.log('✅ High score persistence is present');
    return true;
}

// Test 9: Verify game states
function testGameStates() {
    const gameFile = path.join(__dirname, 'src/game/main.ts');
    const content = fs.readFileSync(gameFile, 'utf8');

    const gameStates = ['menu', 'playing', 'paused', 'clear', 'over'];
    const stateType = 'type GameState = "menu" | "playing" | "paused" | "clear" | "over";';

    if (!content.includes(stateType)) {
        throw new Error('GameState type not found');
    }
    console.log('✅ Game states are defined');
    return true;
}

// Run all tests
function runGameTests() {
    console.log('🧪 Running NOVA BREAKER Game Tests...\n');

    const tests = [
        testGameFileExists,
        testGameCodeLength,
        testGameComponents,
        testGameHtmlExists,
        testPowerUpsSystem,
        testLevelsSystem,
        testAudioSystem,
        testHighScorePersistence,
        testGameStates
    ];

    let passed = 0;
    let failed = 0;

    for (const test of tests) {
        try {
            test();
            passed++;
        } catch (error) {
            console.error(`❌ Test failed: ${error.message}`);
            failed++;
        }
    }

    console.log(`\n📊 Test Results: ${passed} passed, ${failed} failed`);

    if (failed === 0) {
        console.log('🎉 All tests passed! The NOVA BREAKER game is complete and functional.');
    } else {
        console.log('⚠️  Some tests failed. Please review the issues above.');
    }

    return failed === 0;
}

// Execute tests if this file is run directly
if (require.main === module) {
    const success = runGameTests();
    process.exit(success ? 0 : 1);
}

module.exports = { runGameTests };

